from research_helpers import *
base='https://www.abb.com/global/en/areas/robotics/products/robots/'
ps=[];es=[]
def add(name,path,desc,attrs,life='commercial'):
 e=ev(base+path,'Manufacturer product page directly reviewed; exact configuration identity and stated technical data retained.');es.append(e);ps.append(p('ABB '+name,desc,e,life,roles=['commercial_partner'],typ='product',sector='robotics',sub='industrial_robotics',attributes={'manufacturer_model':name,**attrs}))
for name,load in [('IRB 660-180/3.15',180),('IRB 660-250/3.15',250)]:add(name,'articulated-robots/large-robots/irb-660','Four-axis palletizing robot.',{'rated_payload_kg':load,'reach_m':3.15,'axes':4})
add('IRB 760','articulated-robots/large-robots/irb-760','Heavy-payload palletizing robot.',{'rated_payload_kg':450,'reach_m':3.18,'axes':4,'source_rounding_note':'Introduction rounds reach to3.2m; variant field3.18m retained'})
add('IRB 760PT','articulated-robots/large-robots/irb-760','Press-tending robot configuration.',{'rated_payload_kg':450,'reach_m':3.18,'external_axes_and_TwinXbar_configurations':'not separate inferred robot models'})
add('IRB 460','articulated-robots/medium-robots/irb-460','Compact four-axis end-of-line palletizing robot.',{'rated_payload_kg':110,'reach_m':2.4,'axes':4})
for n,axes in [('stop-and-go',3),('moving-line',4)]:add('IRB 5350 '+n+' configuration','paint-robots/irb-5350','Door-opening robot configuration for automotive interior painting.',{'base_model':'IRB 5350','axes':axes,'rated_tower_payload_kg':7,'canonical_name_scope':'descriptive configuration; no invented manufacturer part number'})
for n,desc,attr in [('IRB 5500-22','Integrated exterior-painting robot.',{'rated_wrist_payload_kg':13}),('IRB 5500-25','Elevated-rail robot painting system.',{'rated_tower_payload_kg':13}),('IRB 5500-27','Seven-axis integrated painting robot.',{'rated_wrist_payload_kg':13,'axes':7}),('IRB 5510','Medium-sized paint robot for small workpieces.',{'rated_wrist_payload_kg':13})]:add(n,'paint-robots/'+n.lower().replace(' ','-'),desc,attr)
D=ev('https://library.e.abb.com/public/6d0d2693c9834103b1bc623e921d3734/IRB52_DataSheet_USL.pdf','Historical manufacturer exact IRB52/1.2m and1.45m six-axis paint robots7kg payload. Family still appears in current related offerings, but current exact variant availability unverified.')
for reach in [1.2,1.45]:ps.append(p('ABB IRB 52/'+str(reach),'Six-axis paint robot variant documented in historical manufacturer datasheet.',D,roles=['commercial_partner'],typ='product',sector='robotics',sub='industrial_robotics',attributes={'rated_wrist_payload_kg':7,'reach_m':reach,'axes':6,'current_exact_variant_availability_unverified':True}))
S=ev('https://new.abb.com/news/detail/137499/abb-expands-automation-offering-with-acquisition-of-rotork','Signed robotics divestment still pending in July2026 primary disclosure; latest closing unverified.')
for x in ps:x['evidence'].append(S);x['attributes']['company_relationship_scope']='ABB-branded robotics portfolio; parent commercial relationship; latest SoftBank closing unverified'
cs=[company('ABB Ltd',ps,es+[D,S],'Supplemental13 palletizing/press-tending/painting configurations reviewed;116 prior exact robots retained. IRB52 exact variants historical/current availability unverified; no invention of5350 part numbers. Remaining legacy/current arms, paint applicators, AMRs, controls/software/application cells and nonrobot semiconductor/storage offerings plus corporate sale closing remain to research.')]
(out/'batch-0109.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
